    98    NameRecord* copy (hb_serialize_context_t *c,
    99                      const void *src_base,
   100                      const void *dst_base) const
   101    {
   102      TRACE_SERIALIZE (this);
   103      auto *out = c->embed (this);
   104      if (unlikely (!out)) return_trace (nullptr);
   105      out->offset.serialize_copy (c, src_base + offset, dst_base, length);
   106      return_trace (out);
   107    }
