   115    HBUINT16      platformID;     /* Platform ID. */
   116    HBUINT16      encodingID;     /* Platform-specific encoding ID. */
   117    HBUINT16      languageID;     /* Language ID. */
   118    HBUINT16      nameID;         /* Name ID. */
   119    HBUINT16      length;         /* String length (in bytes). */
   120    NNOffsetTo<UnsizedArrayOf<HBUINT8>>
   121                  offset;         /* String offset from start of storage area (in bytes). */
   122    public:
   123    DEFINE_SIZE_STATIC (12);
   124  };
