   169    unsigned int get_size () const
   170    { return min_size + count * nameRecordZ.item_size; }
   171
   172    template <typename Iterator,
   173              hb_requires (hb_is_iterator_of (Iterator, const NameRecord))>
   174    bool serialize (hb_serialize_context_t *c,
   175                    Iterator it,
   176                    const void *src_string_pool)
   177    {
   178      TRACE_SERIALIZE (this);
   179
   180      if (unlikely (!c->extend_min ((*this))))  return_trace (false);
   181
   182      this->format = 0;
   183      this->count = it.len ();
   184
   185      auto snap = c->snapshot ();
   186      this->nameRecordZ.serialize (c, this->count);
   187      this->stringOffset = c->length ();
   188      c->revert (snap);
   189
   190      const void *dst_string_pool = &(this + this->stringOffset);
   191
   192      + it
   193      | hb_apply ([&] (const NameRecord& _) { c->copy (_, src_string_pool, dst_string_pool); })
   194      ;
   195
   196      if (unlikely (c->ran_out_of_room)) return_trace (false);
   197
   198      assert (this->stringOffset == c->length ());
   199
   200      return_trace (true);
   201    }
   202
   203    bool subset (hb_subset_context_t *c) const
   204    {
   205      TRACE_SUBSET (this);
   206
   207      name *name_prime = c->serializer->start_embed<name> ();
   208      if (unlikely (!name_prime)) return_trace (false);
   209
   210      auto it =
   211      + nameRecordZ.as_array (count)
   212      | hb_filter (c->plan->name_ids, &NameRecord::nameID)
   213      ;
   214
   215      name_prime->serialize (c->serializer, it, hb_addressof (this + stringOffset));
   216      return_trace (name_prime->count);
   217    }
